let liff = null;

export const initializeMiniApp = async () => {
  try {
    if (!window.liff) {
      throw new Error('LIFF SDK not loaded');
    }
    liff = window.liff;
    
    // Khởi tạo LIFF SDK với LIFF ID của Mini App
    await liff.init({ 
      liffId: process.env.REACT_APP_LIFF_ID // Sử dụng LIFF ID từ environment variable
    });

    // Kiểm tra xem có đang chạy trong LINE App không
    const context = liff.getContext();
    if (!context.type || context.type !== 'mini_app') {
      throw new Error('This app must be opened from LINE App');
    }

    return liff;
  } catch (error) {
    console.error('Failed to initialize Mini App:', error);
    throw error;
  }
};

export const getMiniApp = () => {
  if (!liff) {
    throw new Error('LIFF not initialized');
  }
  return liff;
};

export const getProfile = async () => {
  const app = getMiniApp();
  return await app.getProfile();
};

export const getAccessToken = async () => {
  const app = getMiniApp();
  return await app.getAccessToken();
};

