// Mock authenticate với backend
export const authenticateWithBackend = async () => {
  try {
    const app = getMiniApp();
    const profile = await app.getProfile();
    
    // Mock data trả về
    return {
      success: true,
      loginData: {
        token: 'mock_token',
        userId: profile.userId,
        displayName: profile.displayName,
        pictureUrl: profile.pictureUrl,
        statusMessage: profile.statusMessage
      }
    };
  } catch (error) {
    console.error('Authentication error:', error);
    throw error;
  }
};

export const showPopup = (options) => {
  const app = getMiniApp();
  return app.showPopup(options);
}; 